// ServerInterface represents all server handlers.
type ServerInterface interface {
	// 認証済みプレイヤーの情報を返す (レベル進捗を含む)
	// (GET /api/v1/account/me)
	GetPlayer(w http.ResponseWriter, r *http.Request)
	// 1 日のバトル回数制限と残り回数を返す
	// (GET /api/v1/account/me/battle-limit)
	GetBattleLimit(w http.ResponseWriter, r *http.Request)
	// バトル回数を 1 増やす (バトル開始時に gateway が呼び出す)
	// (POST /api/v1/account/me/battle-limit/increment)
	IncrementBattleCount(w http.ResponseWriter, r *http.Request)
	// 経験値を加算する
	// (POST /api/v1/account/me/exp)
	AddExp(w http.ResponseWriter, r *http.Request)
	// プレイヤーが所持する陣営の一覧を返す
	// (GET /api/v1/account/me/factions)
	ListFactions(w http.ResponseWriter, r *http.Request)
	// 陣営の所持を付与する (購入・報酬など)
	// (POST /api/v1/account/me/factions)
	GrantFaction(w http.ResponseWriter, r *http.Request)
	// 初期陣営を選択する (チュートリアル完了時に scenario が呼び出す)
	// (POST /api/v1/account/me/factions/select)
	SelectInitialFaction(w http.ResponseWriter, r *http.Request)
	// 表示名を変更する
	// (PUT /api/v1/account/me/name)
	UpdateName(w http.ResponseWriter, r *http.Request)
	// オンボーディングの名前入力ステップで scenario が呼ぶ表示名の検証
	// (POST /api/v1/account/me/onboarding/name/validate)
	ValidateNameForOnboarding(w http.ResponseWriter, r *http.Request)
	// プレミアム状態を更新する (運用・テスト用。プレミアム状態の正本は shop)
	// (PUT /api/v1/account/me/premium)
	UpdatePremium(w http.ResponseWriter, r *http.Request)
	// プレイヤー設定を返す
	// (GET /api/v1/account/me/settings)
	GetPlayerSettings(w http.ResponseWriter, r *http.Request)
	// プレイヤー設定を部分的に更新する
	// (PUT /api/v1/account/me/settings)
	UpdatePlayerSettings(w http.ResponseWriter, r *http.Request)
	// サービス死活監視 (ClusterIP 内部のみ)
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// Firebase UID からプレイヤーを検索する (gateway などサービス間の照会用)
	// (GET /internal/v1/auth/by-firebase-uid/{firebaseUID})
	GetPlayerByFirebaseUID(w http.ResponseWriter, r *http.Request, firebaseUID string)
	// Firebase UID でログインしてプレイヤー情報を返す
	// (POST /internal/v1/auth/login)
	LoginPlayer(w http.ResponseWriter, r *http.Request)
	// 新規プレイヤーを登録する (gateway が Firebase UID を中継)
	// (POST /internal/v1/auth/register)
	RegisterPlayer(w http.ResponseWriter, r *http.Request)
	// 対戦終了後に両プレイヤーへ経験値を付与する (battle → account)
	// (POST /internal/v1/players/award-game-exp)
	AwardGameExp(w http.ResponseWriter, r *http.Request)
	// 停止で無効になった対戦の消費バトル回数を両プレイヤーに戻す (gateway → account)
	// (POST /internal/v1/players/revert-battle-count)
	RevertBattleCount(w http.ResponseWriter, r *http.Request)
	// 指定プレイヤーの所持陣営一覧を返す (card → account)
	// (GET /internal/v1/players/{playerID}/factions)
	ListPlayerFactions(w http.ResponseWriter, r *http.Request, playerID string)
}

